package com.sakan.iptv;
import android.app.*;
import android.content.*;
import android.content.pm.*;
import android.database.Cursor;
import android.net.Uri;
import android.os.*;
import android.provider.Settings;
import android.widget.Toast;
import androidx.core.content.FileProvider;
import org.json.*;
import java.io.*;
import java.net.*;
import java.security.MessageDigest;
import java.util.*;
import java.util.concurrent.*;


/** Update downloads are verified before offering Android's normal installer. */
final class AppUpdates {
 interface Visibility {boolean visible();}
 private final Activity activity;private final Visibility foreground;private final Handler main=new Handler(Looper.getMainLooper());private final ExecutorService worker=Executors.newSingleThreadExecutor();
 private static final String DEFAULT_REPOSITORY="Ahmedgaafar25/SakanIPTV";
 private final UpdateNotice notice=new UpdateNotice();
 private final DownloadManager downloads;private final android.content.SharedPreferences prefs;private volatile boolean checking=false,verifying=false;private boolean closed=false;
 private final BroadcastReceiver receiver=new BroadcastReceiver(){@Override public void onReceive(Context c,Intent i){if(DownloadManager.ACTION_DOWNLOAD_COMPLETE.equals(i.getAction())&&i.getLongExtra(DownloadManager.EXTRA_DOWNLOAD_ID,-2)==prefs.getLong("downloadId",-1))resume();}};
 AppUpdates(Activity owner,Visibility visible){activity=owner;foreground=visible;prefs=owner.getSharedPreferences("updater",0);downloads=(DownloadManager)owner.getSystemService(Context.DOWNLOAD_SERVICE);IntentFilter f=new IntentFilter(DownloadManager.ACTION_DOWNLOAD_COMPLETE);if(Build.VERSION.SDK_INT>=33)owner.registerReceiver(receiver,f,Context.RECEIVER_EXPORTED);else owner.registerReceiver(receiver,f);}
 private String t(String en,String ar){return "ar".equals(activity.getSharedPreferences("options",0).getString("language","en"))?ar:en;}
 String repository(){String value=prefs.getString("repository",DEFAULT_REPOSITORY);return value.trim().isEmpty()?DEFAULT_REPOSITORY:value;}
 boolean automatic(){return true;}
 void configure(String repo,boolean auto){String value=repo.trim().isEmpty()?DEFAULT_REPOSITORY:ReleaseInfo.repository(repo);if(!value.equals(repository()))notice.reset();prefs.edit().putString("repository",value).remove("automatic").remove("lastCheck").apply();}
 private void ui(Runnable action){main.post(()->{if(!closed&&!activity.isFinishing()&&!activity.isDestroyed()&&foreground.visible())action.run();});}
 private void message(String value){ui(()->Toast.makeText(activity,value,Toast.LENGTH_LONG).show());}
 private JSONObject fetch(String link)throws Exception{
  URL next=new URL(link);for(int redirects=0;redirects<6;redirects++){if(!next.getProtocol().equals("https"))throw new IOException("An update response tried to leave HTTPS");HttpURLConnection c=(HttpURLConnection)next.openConnection();c.setConnectTimeout(12000);c.setReadTimeout(15000);c.setInstanceFollowRedirects(false);c.setRequestProperty("Accept","application/vnd.github+json");c.setRequestProperty("User-Agent","SakanIPTV-Updater");try{int status=c.getResponseCode();if(status>=300&&status<400){String location=c.getHeaderField("Location");if(location==null)throw new IOException("Invalid update redirect");next=new URL(next,location);continue;}if(status!=200)throw new IOException("GitHub HTTP "+status);try(InputStream in=c.getInputStream();ByteArrayOutputStream out=new ByteArrayOutputStream()){byte[] b=new byte[8192];int n;while((n=in.read(b))!=-1){out.write(b,0,n);if(out.size()>2*1024*1024)throw new IOException("Update metadata is too large");}return new JSONObject(out.toString("UTF-8"));}}finally{c.disconnect();}}throw new IOException("Too many update redirects");
 }
 @SuppressWarnings("deprecation") private int installedVersion()throws Exception{return activity.getPackageManager().getPackageInfo(activity.getPackageName(),0).versionCode;}
 void opened(){if(closed)return;notice.opened();check(false);}
 void showPending(){if(closed||activity.isFinishing()||activity.isDestroyed())return;try{ReleaseInfo update=notice.take(installedVersion(),foreground.visible(),prefs.getLong("downloadId",-1)>=0||prefs.getBoolean("ready",false));if(update==null)return;AlertDialog prompt=new AlertDialog.Builder(activity).setTitle(t("Update available","تحديث متاح")).setMessage("Sakan IPTV "+update.versionName+"\n"+t("Download the signed update and confirm installation?","تنزيل التحديث الموقّع ثم تأكيد تثبيته؟")).setPositiveButton(t("Download","تنزيل"),(d,w)->download(update)).setNegativeButton(t("Later","لاحقًا"),null).create();prompt.setOnDismissListener(d->notice.dismissed());prompt.show();}catch(Exception e){notice.dismissed();}}
 void check(boolean manual){if(closed||checking)return;if(manual)notice.opened();String repo=repository();checking=true;if(manual)message(t("Checking for updates…","جارٍ البحث عن تحديث…"));worker.submit(()->{try{JSONObject release=fetch("https://api.github.com/repos/"+ReleaseInfo.repository(repo)+"/releases/latest");JSONObject manifest=fetch(ReleaseInfo.manifestUrl(release,repo));ReleaseInfo update=ReleaseInfo.parse(manifest,release,repo);main.post(()->{if(closed||!repo.equals(repository()))return;notice.found(update);showPending();if(manual){try{if(update.versionCode<=installedVersion())message(t("You have the latest version.","أنت تستخدم أحدث إصدار."));}catch(Exception ignored){}}});}catch(Exception e){if(manual)message(t("Could not check updates. Check the public repository and its release manifest. ","تعذر فحص التحديث. راجع المستودع العام وملف الإصدار. ")+e.getMessage());}finally{checking=false;}});}
 private void download(ReleaseInfo release){try{long existing=prefs.getLong("downloadId",-1);if(existing>=0)downloads.remove(existing);File folder=new File(activity.getExternalFilesDir(null),"updates");folder.mkdirs();File file=new File(folder,"pending.apk");if(file.exists()&&!file.delete())throw new IOException("Could not clear the previous update download");DownloadManager.Request request=new DownloadManager.Request(Uri.parse(release.url)).setTitle("Sakan IPTV "+release.versionName).setDescription(t("Downloading application update","تنزيل تحديث التطبيق")).setNotificationVisibility(DownloadManager.Request.VISIBILITY_VISIBLE_NOTIFY_COMPLETED).setDestinationInExternalFilesDir(activity,"updates","pending.apk");long id=downloads.enqueue(request);prefs.edit().putLong("downloadId",id).putString("sha256",release.sha256).putLong("bytes",release.bytes).putInt("versionCode",release.versionCode).putBoolean("ready",false).apply();message(t("Downloading update. Android will ask you to confirm installation.","جارٍ تنزيل التحديث. سيطلب أندرويد تأكيد التثبيت."));}catch(Exception e){message(t("Update download could not start.","تعذر بدء تنزيل التحديث."));}}
 void resume(){if(closed)return;showPending();if(verifying)return;if(prefs.getBoolean("ready",false)){ui(this::install);return;}long id=prefs.getLong("downloadId",-1);if(id<0)return;try(Cursor c=downloads.query(new DownloadManager.Query().setFilterById(id))){if(!c.moveToFirst())return;int status=c.getInt(c.getColumnIndexOrThrow(DownloadManager.COLUMN_STATUS));if(status==DownloadManager.STATUS_FAILED){prefs.edit().remove("downloadId").apply();message(t("The update download failed. Check again to retry.","فشل تنزيل التحديث. افحص التحديثات لإعادة المحاولة."));return;}if(status!=DownloadManager.STATUS_SUCCESSFUL)return;}catch(Exception e){return;}verifying=true;worker.submit(()->{try{File folder=new File(activity.getFilesDir(),"updates");folder.mkdirs();File target=new File(folder,"verified.apk");MessageDigest digest=MessageDigest.getInstance("SHA-256");long bytes=0;try(InputStream in=new FileInputStream(new File(activity.getExternalFilesDir(null),"updates/pending.apk"));OutputStream out=new FileOutputStream(target)){byte[] b=new byte[8192];int n;while((n=in.read(b))!=-1){bytes+=n;if(bytes>50L*1024*1024)throw new IOException("Update is too large");digest.update(b,0,n);out.write(b,0,n);}}StringBuilder hash=new StringBuilder();for(byte b:digest.digest())hash.append(String.format(Locale.ROOT,"%02x",b&255));if(bytes!=prefs.getLong("bytes",-1)||!hash.toString().equals(prefs.getString("sha256","")))throw new SecurityException("Update checksum mismatch");verifyPackage(target);prefs.edit().putBoolean("ready",true).apply();downloads.remove(id);ui(this::install);}catch(Exception e){prefs.edit().remove("downloadId").putBoolean("ready",false).apply();new File(activity.getFilesDir(),"updates/verified.apk").delete();message(t("Update rejected: signature, package, version or checksum did not match.","تم رفض التحديث: التوقيع أو المعرف أو الإصدار أو بصمة الملف غير مطابق."));}finally{verifying=false;}});}
 @SuppressWarnings("deprecation") private void verifyPackage(File file)throws Exception{PackageManager pm=activity.getPackageManager();int flags=Build.VERSION.SDK_INT>=28?PackageManager.GET_SIGNING_CERTIFICATES:PackageManager.GET_SIGNATURES;PackageInfo candidate=pm.getPackageArchiveInfo(file.getAbsolutePath(),flags),current=pm.getPackageInfo(activity.getPackageName(),flags);if(candidate==null||!current.packageName.equals(candidate.packageName)||candidate.versionCode<=current.versionCode||candidate.versionCode!=prefs.getInt("versionCode",-1))throw new SecurityException("Invalid update package or version");android.content.pm.Signature[] a=Build.VERSION.SDK_INT>=28?candidate.signingInfo.getApkContentsSigners():candidate.signatures,b=Build.VERSION.SDK_INT>=28?current.signingInfo.getApkContentsSigners():current.signatures;if(a==null||b==null||a.length!=b.length)throw new SecurityException("Signer count mismatch");Set<String> expected=new HashSet<>();for(android.content.pm.Signature s:b)expected.add(s.toCharsString());for(android.content.pm.Signature s:a)if(!expected.contains(s.toCharsString()))throw new SecurityException("Signing certificate mismatch");}
 private void install(){File apk=new File(activity.getFilesDir(),"updates/verified.apk");try{verifyPackage(apk);}catch(Exception e){prefs.edit().putBoolean("ready",false).remove("downloadId").apply();apk.delete();return;}if(Build.VERSION.SDK_INT>=26&&!activity.getPackageManager().canRequestPackageInstalls()){new AlertDialog.Builder(activity).setTitle(t("Allow app updates","السماح بتحديث التطبيق")).setMessage(t("Enable installation from Sakan IPTV, then return to continue.","اسمح بالتثبيت من Sakan IPTV ثم ارجع لاستكمال التحديث.")).setPositiveButton(t("Open settings","فتح الإعدادات"),(d,w)->{try{activity.startActivity(new Intent(Settings.ACTION_MANAGE_UNKNOWN_APP_SOURCES,Uri.parse("package:"+activity.getPackageName())));}catch(Exception e){message(t("Open Android's install unknown apps settings manually.","افتح إعداد السماح بتثبيت التطبيقات في أندرويد يدويًا."));}}).setNegativeButton(t("Later","لاحقًا"),null).show();return;}try{Uri uri=FileProvider.getUriForFile(activity,activity.getPackageName()+".updates",apk);Intent intent=new Intent(Intent.ACTION_VIEW).setDataAndType(uri,"application/vnd.android.package-archive").addFlags(Intent.FLAG_GRANT_READ_URI_PERMISSION);activity.startActivity(intent);prefs.edit().putBoolean("ready",false).remove("downloadId").apply();}catch(Exception e){message(t("Could not open the Android installer.","تعذر فتح مثبت تطبيقات أندرويد."));}}
 void close(){closed=true;try{activity.unregisterReceiver(receiver);}catch(Exception ignored){}worker.shutdownNow();}
}
